import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        ArrayList<Integer> 柜子 = new ArrayList<>();
        int 合计 = 0;
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            柜子.add(x);
            合计 = 合计 + x;
        }
        System.out.println("柜子里装了 " + 柜子.size() + " 件");
        System.out.println("合计 " + 合计);
    }
}
